1	import { test, expect } from '@playwright/test';
2	
3	const PAGES = [
4	  { link: 'Home', file: 'index.html', heading: 'Small things that make a desk feel like yours' },
5	  { link: 'Products', file: 'products.html', heading: 'Products' },
6	  { link: 'Pricing', file: 'pricing.html', heading: 'Pricing' },
7	  { link: 'Orders', file: 'orders.html', heading: 'Orders' },
8	  { link: 'About', file: 'about.html', heading: 'About' },
9	  { link: 'Contact', file: 'contact.html', heading: 'Contact' },
10	];
11	
12	test.describe('navigation', () => {
13	  for (const { link, file, heading } of PAGES) {
14	    test(`the ${link} link opens ${file}`, async ({ page }) => {
15	      await page.goto(file === 'index.html' ? '/about.html' : '/');
16	      await page.getByRole('navigation', { name: 'Main' }).getByRole('link', { name: link, exact: true }).click();
17	      await expect(page).toHaveURL(new RegExp(`/${file.replace('.', '\\.')}$`));
18	      await expect(page.getByRole('heading', { level: 1 })).toHaveText(heading);
19	      await expect(
20	        page.getByRole('navigation', { name: 'Main' }).getByRole('link', { name: link, exact: true }),
21	      ).toHaveAttribute('aria-current', 'page');
22	    });
23	  }
24	
25	  test('every page lists the same six links', async ({ page }) => {
26	    for (const { file } of PAGES) {
27	      await page.goto(`/${file}`);
28	      await expect(page.getByRole('navigation', { name: 'Main' }).getByRole('link')).toHaveText(
29	        PAGES.map((p) => p.link),
30	      );
31	    }
32	  });
33	
34	  test('on a phone the menu opens from the Menu button', async ({ page }) => {
35	    await page.setViewportSize({ width: 390, height: 844 });
36	    await page.goto('/');
37	    const nav = page.getByRole('navigation', { name: 'Main' });
38	    const menu = page.getByRole('button', { name: 'Menu' });
39	    await expect(nav).toBeHidden();
40	    await menu.click();
41	    await expect(nav).toBeVisible();
42	    await expect(menu).toHaveAttribute('aria-expanded', 'true');
43	    await nav.getByRole('link', { name: 'Pricing', exact: true }).click();
44	    await expect(page).toHaveURL(/\/pricing\.html$/);
45	  });
46	});
47	
48	test.describe('contact form', () => {
49	  test('an empty form shows what is needed and sends nothing', async ({ page }) => {
50	    await page.goto('/contact.html');
51	    await page.getByRole('button', { name: 'Send message' }).click();
52	    await expect(page.getByText('Please enter your name.')).toBeVisible();
53	    await expect(page.getByText('Please enter a valid email address.')).toBeVisible();
54	    await expect(page.getByText('Please write at least 10 characters.')).toBeVisible();
55	    await expect(page.getByText('Please agree before sending.')).toBeVisible();
56	    await expect(page.getByRole('status')).toBeHidden();
57	  });
58	
59	  test('a bad email address is refused', async ({ page }) => {
60	    await page.goto('/contact.html');
61	    await page.getByLabel('Name', { exact: true }).fill('Dana');
62	    await page.getByLabel('Email', { exact: true }).fill('dana-at-example');
63	    await page.getByLabel('Message', { exact: true }).fill('Where is my order 1041?');
64	    await page.getByLabel('You may store this message').check();
65	    await page.getByRole('button', { name: 'Send message' }).click();
66	    await expect(page.getByText('Please enter a valid email address.')).toBeVisible();
67	    await expect(page.getByText('Please enter your name.')).toBeHidden();
68	    await expect(page.getByRole('status')).toBeHidden();
69	  });
70	
71	  test('a complete form is sent and thanks the sender by name', async ({ page }) => {
72	    await page.goto('/contact.html');
73	    await page.getByLabel('Name', { exact: true }).fill('Dana Whitfield');
74	    await page.getByLabel('Email', { exact: true }).fill('[EMAIL]');
75	    await page.getByLabel('Topic', { exact: true }).selectOption('A product');
76	    await page.getByLabel('Message', { exact: true }).fill('Does the Aurora Lamp come in black?');
77	    await page.getByLabel('You may store this message').check();
78	    await page.getByRole('button', { name: 'Send message' }).click();
79	    await expect(page.getByRole('status')).toHaveText(
80	      'Thanks, Dana Whitfield. We will reply within one business day.',
81	    );
82	    await expect(page.getByRole('button', { name: 'Send message' })).toBeHidden();
83	  });
84	});
85	
86	test.describe('newsletter', () => {
87	  test('a valid address is accepted', async ({ page }) => {
88	    await page.goto('/');
89	    await page.getByLabel('Email address').fill('[EMAIL]');
90	    await page.getByRole('button', { name: 'Subscribe' }).click();
91	    await expect(page.getByText('You are on the list. Look out for the next issue.')).toBeVisible();
92	    await expect(page.getByLabel('Email address')).toHaveValue('');
93	  });
94	
95	  test('an invalid address is refused', async ({ page }) => {
96	    await page.goto('/');
97	    await page.getByLabel('Email address').fill('dana');
98	    await page.getByRole('button', { name: 'Subscribe' }).click();
99	    await expect(page.getByText('Please enter a valid email address.')).toBeVisible();
100	  });
101	});
102	
103	test.describe('order details', () => {
