const path = require('node:path');

const project = process.argv[2];
const port = 43117;
const server = spawn(process.execPath, [path.join(project, 'server.js')], {
  cwd: project,
  env: { ...process.env, PORT: String(port) },
  stdio: 'inherit',
});

(async () => {
