    await page.screenshot({ path: `${process.env.TMPDIR}/contact-${name}.png`, fullPage: true });
    if (name === 'desktop') {
      const info = await page.evaluate(() => {
        const pick = (sel) => {
          const el = document.querySelector(sel);
          if (!el) return { sel, missing: true };
          const r = el.getBoundingClientRect();
          const cs = getComputedStyle(el);
          return { sel, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: cs.display, position: cs.position, overflow: cs.overflow, font: cs.fontFamily, fontSize: cs.fontSize };
