        return ['.contact-grid', '#contact-form', '.form-input', '.card', 'main', '.page-head', 'body'].map(pick);
      });
      console.log(JSON.stringify(info, null, 2));
    }
    await page.close();
  }
  await browser.close();
  server.kill();
})().catch((e) => { console.error(e); server.kill(); process.exit(1); });
